        var plant=ChaosHut(0,"h09T",new Vector2(-148,32));var inside=ChaosHut(0,"h05X",new Vector2(-143,32));var launcher=ChaosHut(1,"h048",new Vector2(-155,32));float mana=launcher.mana;
        Check(!match.CastNorthernBuilding(launcher,"A04J",inside.id)&&launcher.mana==mana,"Power plant coverage prevents selecting protected buildings for a Northern frost bolt");var outside=ChaosHut(0,"h05X",new Vector2(-141.9f,32));Check(match.CastNorthernBuilding(launcher,"A04J",outside.id),"Frost launcher can still select the first unpowered building beyond native coverage");launcher.paused=true;NorthTime(3);Check(match.FrostDisabled(outside)>0&&match.FrostDisabled(inside)==0,"Actual frost impact preserves power-plant protection and freezes the unpowered target");
        MechClear();plant=ChaosHut(0,"h09T",new Vector2(-148,32));inside=ChaosHut(0,"h05X",plant.position+Vector2.right*(251f/30));outside=ChaosHut(0,"h05X",plant.position+Vector2.right*(253f/30));var enemy=ChaosHut(1,"h049",plant.position+Vector2.right*(200f/30));
        foreach(var h in new[]{inside,outside,enemy,plant}){h.paused=true;match.HellCurses.Add(new HumanMatch.HellCurse {target=h.id,team=1-h.team,left=100,dps=1});match.NorthernFreezes.Add(new HumanMatch.NorthernFreeze {target=-h.id-2,team=1-h.team,id="Bfrz",left=100});}
        float wait=match.MechCleanseRemaining;NorthTime(Mathf.Max(0,wait-.1f));Check(match.BuildingDisabled(inside)>0&&match.BuildingDisabled(enemy)>0,"Power-plant cleansing waits for the native four-second cadence");NorthTime(.2f);
        Check(match.BuildingDisabled(inside)==0&&match.BuildingDisabled(enemy)==0,"Power-plant cleansing removes ally and enemy disabling jobs inside radius 252");Check(match.BuildingDisabled(outside)>0&&match.BuildingDisabled(plant)>0,"Cleansing excludes its own plant and buildings beyond radius 252");Check(!match.HellCurses.Any(c=>c.target==inside.id)&&!match.NorthernFreezes.Any(c=>c.target==-inside.id-2),"Cleansing removes actual Hell Fist and Northern DOT records");
